70	// NewHandlerWithReadiness builds the same public HTTP surface as NewHandler but
71	// answers every request — including GET /healthz — with a 503 JSON error until
72	// ready reports that the database is open and the listener is accepting
73	// connections. Once ready, responses are byte-for-byte what NewHandler emits;
74	// readiness is one-way, so a later flip back is not part of the contract.
75	func NewHandlerWithReadiness(s *store.Store, ready func() bool) http.Handler {
76		h := NewHandler(s)
77		if ready == nil {
78			return h
79		}
80		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
81			if !ready() {
82				writeError(w, http.StatusServiceUnavailable, "service is not ready")
83				return
84			}
85			h.ServeHTTP(w, r)
86		})
87	}
