89	// NewHandler builds the public HTTP surface backed by s.
90	func NewHandler(s *store.Store) http.Handler {
91		mux := http.NewServeMux()
92	
93		mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
94			writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
95		})
96	
97		mux.HandleFunc("POST /v1/devices", func(w http.ResponseWriter, r *http.Request) {
98			handleRegisterDevice(s, w, r)
99		})
100		// Non-POST verbs on the exact collection path: the method-less pattern is
101		// less specific than POST above, so it only catches the rest and answers a
102		// JSON 404 instead of ServeMux's slash redirect.
103		mux.HandleFunc("/v1/devices", func(w http.ResponseWriter, _ *http.Request) {
104			writeError(w, http.StatusNotFound, "unknown device path")
105		})
106		mux.HandleFunc("/v1/sessions", func(w http.ResponseWriter, _ *http.Request) {
107			writeError(w, http.StatusNotFound, "unknown session path")
108		})
109		mux.HandleFunc("POST /v1/devices/{deviceId}/sessions", func(w http.ResponseWriter, r *http.Request) {
110			handleCreateSession(s, w, r)
111		})
112		mux.HandleFunc("DELETE /v1/devices/{deviceId}/sessions/{sessionId}", func(w http.ResponseWriter, r *http.Request) {
113			handleDeleteSession(s, w, r)
114		})
115		mux.HandleFunc("POST /v1/devices/{deviceId}/attachments", func(w http.ResponseWriter, r *http.Request) {
116			handleCreateAttachment(s, w, r)
117		})
118		mux.HandleFunc("PUT /v1/devices/{deviceId}/attachments/{attachmentId}/chunks/{index}", func(w http.ResponseWriter, r *http.Request) {
119			handlePutChunk(s, w, r)
120		})
121		mux.HandleFunc("POST /v1/devices/{deviceId}/attachments/{attachmentId}/complete", func(w http.ResponseWriter, r *http.Request) {
122			handleCompleteAttachment(s, w, r)
123		})
124		mux.HandleFunc("GET /v1/devices/{deviceId}/attachments/{attachmentId}", func(w http.ResponseWriter, r *http.Request) {
125			handleGetAttachment(s, w, r)
126		})
127		mux.HandleFunc("GET /v1/devices/{deviceId}/attachments/{attachmentId}/chunks/{index}", func(w http.ResponseWriter, r *http.Request) {
128			handleGetChunk(s, w, r)
129		})
130		mux.HandleFunc("GET /v1/sessions/{sessionId}/documents/{documentId}/changes", func(w http.ResponseWriter, r *http.Request) {
131			handleSessionChanges(s, w, r)
132		})
133		// Any other path under the new namespaces is a JSON 404 rather than
134		// ServeMux's plain-text one: every failure of a new endpoint answers JSON.
135		// Exact method-patterns above take precedence over these subtree patterns.
136		mux.HandleFunc("/v1/devices/{rest...}", func(w http.ResponseWriter, _ *http.Request) {
137			writeError(w, http.StatusNotFound, "unknown device/session path")
138		})
139		mux.HandleFunc("/v1/sessions/{rest...}", func(w http.ResponseWriter, _ *http.Request) {
140			writeError(w, http.StatusNotFound, "unknown session path")
141		})
142	
143		mux.HandleFunc("POST /v1/documents/{documentID}/changes", func(w http.ResponseWriter, r *http.Request) {
144			handlePostChanges(s, w, r)
145		})
146		mux.HandleFunc("GET /v1/documents/{documentID}/changes", func(w http.ResponseWriter, r *http.Request) {
147			handleListChanges(s, w, r)
148		})
149		mux.HandleFunc("POST /v1/documents/{documentID}/merge", func(w http.ResponseWriter, r *http.Request) {
150			handleMergeChange(s, w, r)
151		})
152		mux.HandleFunc("POST /v1/documents/{documentID}/snapshots", func(w http.ResponseWriter, r *http.Request) {
153			handlePostSnapshot(s, w, r)
154		})
155		mux.HandleFunc("GET /v1/documents/{documentID}/snapshots/{cursor}", func(w http.ResponseWriter, r *http.Request) {
156			handleGetSnapshot(s, w, r)
157		})
158		mux.HandleFunc("POST /v1/documents/{documentID}/restore", func(w http.ResponseWriter, r *http.Request) {
159			handleRestore(s, w, r)
160		})
161		mux.HandleFunc("POST /v1/documents/{documentID}/permissions", func(w http.ResponseWriter, r *http.Request) {
162			handleSetPermission(s, w, r)
163		})
164	
165		// ServeMux treats any empty path segment (the doubled slash in
166		// /v1/documents//..., /v1/devices//sessions or
167		// /v1/sessions//documents/...) as an unclean path and answers with a 307
168		// HTML redirect (a 404 in a real client). The API contract is a 400 JSON
169		// error for an empty identifier, so intercept those paths before the mux
170		// sees them. A trailing slash empties the final id of the device/session
171		// routes and is rejected there for the same reason; the document routes
172		// keep their pre-existing ServeMux behavior.
173		return emptyIDGuard(mux)
174	}
175	
176	// emptyIDGuard rejects requests carrying an empty path identifier with a 400
177	// JSON error instead of letting ServeMux emit its HTML redirect or a
178	// plain-text 404.
179	//
180	// The document family keeps its original rule (an empty documentID, i.e. the
181	// prefix /v1/documents//); other odd paths there retain their old response so
182	// the pre-existing surface is unchanged. The new device/session families are
183	// stricter: any doubled slash (an empty deviceId, sessionId or documentId
184	// segment) or a trailing slash (an empty final id) is a 400 JSON error.
185	func emptyIDGuard(next http.Handler) http.Handler {
186		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
187			p := r.URL.Path
188	
189			documentSegmentEmpty := strings.HasPrefix(p, "/v1/documents//")
190			newFamilySegmentEmpty := false
191			if strings.HasPrefix(p, "/v1/devices/") || strings.HasPrefix(p, "/v1/sessions/") {
192				newFamilySegmentEmpty = strings.Contains(p, "//") || strings.HasSuffix(p, "/")
193			}
194	
195			if documentSegmentEmpty || newFamilySegmentEmpty {
196				writeError(w, http.StatusBadRequest, "path identifiers must be non-empty strings")
197				return
198			}
199			next.ServeHTTP(w, r)
200		})
201	}
