203	// Handler exposes the HTTP surface over a private in-memory store. Use
204	// NewHandler with a durable store for real deployments.
205	func Handler() http.Handler {
206		s, err := store.Open("")
207		if err != nil {
208			log.Fatalf("open in-memory store: %v", err)
209		}
210		return NewHandler(s)
211	}
