240	func handleRegisterDevice(s *store.Store, w http.ResponseWriter, r *http.Request) {
241		var req deviceRequest
242		if !decodeJSONBody(w, r, &req) {
243			return
244		}
245		if req.DeviceID == "" {
246			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
247			return
248		}
249	
250		created, err := s.RegisterDevice(req.DeviceID)
251		if err != nil {
252			writeError(w, http.StatusInternalServerError, "failed to register device")
253			return
254		}
255	
256		writeJSON(w, http.StatusOK, map[string]any{"deviceId": req.DeviceID, "created": created})
257	}
