259	func handleCreateSession(s *store.Store, w http.ResponseWriter, r *http.Request) {
260		deviceID := r.PathValue("deviceId") // route pattern + guard guarantee non-empty
261	
262		var req sessionRequest
263		if !decodeJSONBody(w, r, &req) {
264			return
265		}
266		if req.SessionID == "" {
267			writeError(w, http.StatusBadRequest, "sessionId must be a non-empty string")
268			return
269		}
270	
271		created, err := s.CreateSession(deviceID, req.SessionID)
272		if err != nil {
273			var conflict *store.ErrSessionConflict
274			switch {
275			case errors.Is(err, store.ErrDeviceNotFound):
276				writeError(w, http.StatusNotFound, "device not found")
277			case errors.As(err, &conflict):
278				writeError(w, http.StatusConflict, "sessionId already belongs to another device: "+conflict.ID)
279			default:
280				writeError(w, http.StatusInternalServerError, "failed to create session")
281			}
282			return
283		}
284	
285		writeJSON(w, http.StatusOK, map[string]any{"sessionId": req.SessionID, "created": created})
286	}
