304	func handlePostChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
305		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
306	
307		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
308		if err != nil || mediaType != "application/json" {
309			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
310			return
311		}
312	
313		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
314		var req postRequest
315		dec := json.NewDecoder(r.Body)
316		if err := dec.Decode(&req); err != nil {
317			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
318			return
319		}
320		// Reject trailing data after the JSON object.
321		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
322			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
323			return
324		}
325	
326		if req.DeviceID == "" {
327			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
328			return
329		}
330		if len(req.Changes) == 0 {
331			writeError(w, http.StatusBadRequest, "changes must be a non-empty array")
332			return
333		}
334	
335		changes := make([]store.Change, len(req.Changes))
336		seen := make(map[string]struct{}, len(req.Changes))
337		for i, c := range req.Changes {
338			if c.ID == "" {
339				writeError(w, http.StatusBadRequest, "each change must have a non-empty string id")
340				return
341			}
342			if len(c.Payload) == 0 {
343				writeError(w, http.StatusBadRequest, "each change must carry a JSON payload")
344				return
345			}
346			if _, dup := seen[c.ID]; dup {
347				writeError(w, http.StatusBadRequest, "duplicate change id within batch: "+c.ID)
348				return
349			}
350			seen[c.ID] = struct{}{}
351			changes[i] = store.Change{ID: c.ID, DeviceID: req.DeviceID, Payload: c.Payload}
352		}
353	
354		results, err := s.PostChanges(documentID, changes)
355		if err != nil {
356			var conflict *store.ErrConflict
357			if errors.As(err, &conflict) {
358				writeError(w, http.StatusConflict, "change id already exists with different deviceId or payload: "+conflict.ID)
359				return
360			}
361			writeError(w, http.StatusInternalServerError, "failed to commit changes")
362			return
363		}
364	
365		writeJSON(w, http.StatusOK, map[string]any{"results": results})
366	}
