368	func handleMergeChange(s *store.Store, w http.ResponseWriter, r *http.Request) {
369		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
370	
371		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
372		if err != nil || mediaType != "application/json" {
373			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
374			return
375		}
376	
377		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
378		var req mergeRequest
379		dec := json.NewDecoder(r.Body)
380		if err := dec.Decode(&req); err != nil {
381			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
382			return
383		}
384		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
385			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
386			return
387		}
388	
389		if req.DeviceID == "" {
390			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
391			return
392		}
393		// baseCursor must be present and a non-negative integer (no fractions,
394		// strings, booleans or null).
395		if len(req.BaseCursor) == 0 {
396			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
397			return
398		}
399		baseCursor, ok := parseNonNegativeInt(req.BaseCursor)
400		if !ok {
401			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
402			return
403		}
404		if req.Change == nil {
405			writeError(w, http.StatusBadRequest, "change must be an object")
406			return
407		}
408		if req.Change.ID == "" {
409			writeError(w, http.StatusBadRequest, "change.id must be a non-empty string")
410			return
411		}
412		if len(req.Change.Payload) == 0 || !isJSONObject(req.Change.Payload) {
413			writeError(w, http.StatusBadRequest, "change.payload must be a JSON object")
414			return
415		}
416	
417		result, err := s.MergeChange(documentID, baseCursor, store.Change{
418			ID:       req.Change.ID,
419			DeviceID: req.DeviceID,
420			Payload:  req.Change.Payload,
421		})
422		if err != nil {
423			var conflict *store.ErrConflict
424			switch {
425			case errors.Is(err, store.ErrStaleCursor):
426				writeError(w, http.StatusBadRequest, "baseCursor is unknown or greater than the current cursor")
427				return
428			case errors.As(err, &conflict):
429				writeError(w, http.StatusConflict, "merge conflicts with existing changes: "+conflict.ID)
430				return
431			default:
432				writeError(w, http.StatusInternalServerError, "failed to merge change")
433				return
434			}
435		}
436	
437		writeJSON(w, http.StatusOK, result)
438	}
