440	func handlePostSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
441		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
442	
443		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
444		if err != nil || mediaType != "application/json" {
445			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
446			return
447		}
448	
449		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
450		var req snapshotPostRequest
451		dec := json.NewDecoder(r.Body)
452		if err := dec.Decode(&req); err != nil {
453			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
454			return
455		}
456		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
457			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
458			return
459		}
460	
461		cursor, ok := parseNonNegativeInt(req.Cursor)
462		if !ok {
463			writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
464			return
465		}
466		if len(req.State) == 0 {
467			writeError(w, http.StatusBadRequest, "state is required")
468			return
469		}
470	
471		created, err := s.PutSnapshot(documentID, cursor, req.State)
472		if err != nil {
473			var conflict *store.ErrSnapshotConflict
474			switch {
475			case errors.Is(err, store.ErrSnapshotBase):
476				writeError(w, http.StatusBadRequest, "document is unknown or cursor is not an existing cursor")
477				return
478			case errors.As(err, &conflict):
479				writeError(w, http.StatusConflict, "snapshot already exists with a different state")
480				return
481			default:
482				writeError(w, http.StatusInternalServerError, "failed to store snapshot")
483				return
484			}
485		}
486	
487		writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "created": created})
488	}
