512	func handleRestore(s *store.Store, w http.ResponseWriter, r *http.Request) {
513		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
514	
515		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
516		if err != nil || mediaType != "application/json" {
517			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
518			return
519		}
520	
521		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
522		var req restoreRequest
523		dec := json.NewDecoder(r.Body)
524		if err := dec.Decode(&req); err != nil {
525			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
526			return
527		}
528		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
529			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
530			return
531		}
532	
533		if req.DeviceID == "" {
534			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
535			return
536		}
537		if req.ChangeID == "" {
538			writeError(w, http.StatusBadRequest, "changeId must be a non-empty string")
539			return
540		}
541		// snapshotCursor must be present and a positive integer (no fractions,
542		// strings, booleans, null or zero).
543		if len(req.SnapshotCursor) == 0 {
544			writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
545			return
546		}
547		snapshotCursor, ok := parsePositiveInt(req.SnapshotCursor)
548		if !ok {
549			writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
550			return
551		}
552	
553		result, err := s.RestoreSnapshot(documentID, req.DeviceID, req.ChangeID, snapshotCursor)
554		if err != nil {
555			var conflict *store.ErrRestoreConflict
556			switch {
557			case errors.Is(err, store.ErrSnapshotNotFound):
558				writeError(w, http.StatusNotFound, "snapshot not found")
559				return
560			case errors.As(err, &conflict):
561				writeError(w, http.StatusConflict, "change id already exists with a different deviceId, snapshotCursor or source state: "+req.ChangeID)
562				return
563			default:
564				writeError(w, http.StatusInternalServerError, "failed to restore snapshot")
565				return
566			}
567		}
568	
569		writeJSON(w, http.StatusOK, result)
570	}
