	}

	// The snapshot itself is still readable and old rows untouched.
	w, snap := doRequest(t, h, http.MethodGet, "/v1/documents/doc1/snapshots/2")
	if w.Code != http.StatusOK || snap["state"].(map[string]any)["text"] != "hello" {
