73	// startProcess launches syncd with the given environment and waits for the
74	// startup line, returning the actual endpoint parsed from it.
75	func startProcess(t *testing.T, env ...string) *process {
76		t.Helper()
77		p := &process{
78			cmd:    exec.Command(buildBinary(t)),
79			out:    &safeBuffer{},
80			exited: make(chan error, 1),
81		}
82		p.cmd.Env = append(os.Environ(), env...)
83		p.cmd.Stdout = p.out
84		p.cmd.Stderr = p.out
85		if err := p.cmd.Start(); err != nil {
86			t.Fatalf("start syncd: %v", err)
87		}
88		go func() { p.exited <- p.cmd.Wait() }()
89	
90		deadline := time.Now().Add(15 * time.Second)
91		ticker := time.NewTicker(5 * time.Millisecond)
92		defer ticker.Stop()
93		for time.Now().Before(deadline) {
94			if m := listeningLine.FindStringSubmatch(p.out.String()); m != nil {
95				p.addr = m[1]
96				p.dataDir = m[2]
97				return p
98			}
99			select {
100			case err := <-p.exited:
101				t.Fatalf("syncd exited before reporting its endpoint (err=%v); output:\n%s", err, p.out.String())
102			default:
103			}
104			<-ticker.C
105		}
106		_ = p.cmd.Process.Kill()
107		<-p.exited
108		t.Fatalf("syncd never reported its endpoint; output:\n%s", p.out.String())
109		return nil
110	}
