112	func (p *process) terminate(t *testing.T) int {
113		t.Helper()
114		if err := p.cmd.Process.Signal(syscall.SIGTERM); err != nil {
115			t.Fatalf("send SIGTERM: %v", err)
116		}
117		select {
118		case err := <-p.exited:
119			if ee, ok := err.(*exec.ExitError); ok {
120				return ee.ExitCode()
121			}
122			if err != nil {
123				t.Fatalf("wait for syncd: %v", err)
124			}
125			return 0
126		case <-time.After(10 * time.Second):
127			_ = p.cmd.Process.Kill()
128			t.Fatalf("process did not exit within 10s; output:\n%s", p.out.String())
129		}
130		return -1
131	}
