307	
308		first := startProcess(t, "SYNC_ADDR="+addr, "SYNC_DATA="+dataPath)
309		status, body := processJSON(t, http.MethodPost, "http://"+first.addr+"/v1/devices",
310			map[string]string{"deviceId": "persisted"})
311		if status != http.StatusOK || body["created"] != true {
312			t.Fatalf("register: %d %v", status, body)
313		}
314		if code := first.terminate(t); code != 0 {
315			t.Fatalf("SIGTERM exit code = %d, want 0", code)
316		}
317	
318		second := startProcess(t, "SYNC_ADDR="+addr, "SYNC_DATA="+dataPath)
319		defer second.cmd.Process.Kill()
320		status, body = processJSON(t, http.MethodPost, "http://"+second.addr+"/v1/devices",
321			map[string]string{"deviceId": "persisted"})
322		if status != http.StatusOK || body["created"] != false {
323			t.Fatalf("re-register after restart: %d %v, want created=false", status, body)
324		}
325	}
326	
327	// Two real processes started at once on :0 with distinct data paths each get
328	// their own endpoint from their own log line, and a device registered in one
329	// is absent from the other.
330	func TestProcessTwoEphemeralInstances(t *testing.T) {
331		a := startProcess(t, "SYNC_ADDR=127.0.0.1:0", "SYNC_DATA="+filepath.Join(t.TempDir(), "a.db"))
332		defer a.cmd.Process.Kill()
333		b := startProcess(t, "SYNC_ADDR=127.0.0.1:0", "SYNC_DATA="+filepath.Join(t.TempDir(), "b.db"))
334		defer b.cmd.Process.Kill()
335		if a.addr == b.addr {
336			t.Fatalf("both processes report endpoint %s", a.addr)
337		}
338	
339		if status, body := processJSON(t, http.MethodPost, "http://"+a.addr+"/v1/devices",
340			map[string]string{"deviceId": "shared-name"}); status != http.StatusOK || body["created"] != true {
341			t.Fatalf("register in A: %d %v", status, body)
342		}
343		if status, body := processJSON(t, http.MethodPost, "http://"+b.addr+"/v1/devices",
344			map[string]string{"deviceId": "shared-name"}); status != http.StatusOK || body["created"] != true {
345			t.Fatalf("register in B: %d %v, want independent created=true", status, body)
346		}
347		if status, body := processJSON(t, http.MethodPost, "http://"+a.addr+"/v1/devices",
348			map[string]string{"deviceId": "shared-name"}); status != http.StatusOK || body["created"] != false {
349			t.Fatalf("repeat register in A: %d %v, want created=false", status, body)
350		}
351		if code := a.terminate(t); code != 0 {
352			t.Fatalf("A exit = %d", code)
353		}
354		if code := b.terminate(t); code != 0 {
355			t.Fatalf("B exit = %d", code)
356		}
357	}
