// wait is not registered. An unknown document is treated as "no rows": a poll
// parks (subject to wait) and returns empty with nextCursor 0; a first change
// for the document then delivers it.
func (s *Store) WaitForChanges(ctx context.Context, documentID string, after, limit int64, wait time.Duration) (changes []ListedChange, nextCursor int64, timedOut bool, err error) {
