// long-poll/replay endpoints but carries a trailing slash or extra path
// segments. ServeMux would answer those with a 301 redirect (or plain-text
// 404); the new endpoints promise a JSON error and never a redirect, so any
// path under the exact endpoint location that is not the location itself is a
// malformed 400.
func malformedNewDocumentPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/documents/")
	if !ok {
		return false
	}
	_, tail, found := strings.Cut(rest, "/")
	if !found {
		return false
	}
	for _, base := range []string{"changes/poll", "replay"} {
		if tail == base {
			return false
		}
		if strings.HasPrefix(tail, base+"/") {
			return true
		}
	}
	return false
}

