14	// waitResult captures one WaitForChanges outcome for the goroutine tests.
15	type waitResult struct {
16		changes  []ListedChange
17		next     int64
18		timedOut bool
19		err      error
20	}
21	
22	func waitInBackground(ctx context.Context, s *Store, doc string, after, limit int64, wait time.Duration) <-chan waitResult {
23		ch := make(chan waitResult, 1)
24		go func() {
25			changes, next, timedOut, err := s.WaitForChanges(ctx, doc, after, limit, wait)
26			ch <- waitResult{changes: changes, next: next, timedOut: timedOut, err: err}
27		}()
28		return ch
29	}
