// malformedNewDocumentPath reports whether p targets one of the new
// long-poll/replay endpoints but is not that endpoint's exact location: a
// missing/empty segment, a trailing slash, extra segments, or a "poll"/"replay"
// segment anywhere short of the registered shape. ServeMux would answer those
// with a 301 redirect or a plain-text 404/405; the new endpoints promise a
// JSON error and never a redirect, so every such path is a malformed 400.
func malformedNewDocumentPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/documents/")
	if !ok {
		return false
	}
	segments := strings.Split(rest, "/")
	mentionsNewEndpoint := false
	for _, seg := range segments {
		if seg == "poll" || seg == "replay" {
			mentionsNewEndpoint = true
			break
		}
	}
	if !mentionsNewEndpoint {
		return false
	}
	// The only valid shapes are {documentID}/changes/poll and
	// {documentID}/replay with every segment non-empty. A document may itself
	// be named "poll" or "replay"; the full segment layout is what matters.
	if len(segments) == 3 && segments[0] != "" && segments[1] == "changes" && segments[2] == "poll" {
		return false
	}
	if len(segments) == 2 && segments[0] != "" && segments[1] == "replay" {
		return false
	}
	return true
}

